const DB='tradeflow-lite-v1', STORES=['customers','quotes','jobs','tasks','events','expenses','settings','opportunities','pins'];let db,tab='dashboard',query='',modal=null,toast='';let prefs={company:'TradeFlow Lite',accent:'#087f91',categories:['Electrical','Plumbing','Construction','Renovation','Other']};
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const euro=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(Number(n)||0);const today=()=>new Date().toISOString().slice(0,10);const uid=()=>crypto.randomUUID();
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,4);r.onupgradeneeded=()=>{for(const s of STORES)if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s,{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function tx(store,mode,cb){return new Promise((res,rej)=>{const t=db.transaction(store,mode),s=t.objectStore(store),r=cb(s);t.oncomplete=()=>res(r?.result);t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)})}const all=s=>tx(s,'readonly',x=>x.getAll());const put=(s,v)=>tx(s,'readwrite',x=>x.put(v));const del=(s,id)=>tx(s,'readwrite',x=>x.delete(id));const get=(s,id)=>tx(s,'readonly',x=>x.get(id));
async function event(text){await put('events',{id:uid(),text,date:new Date().toISOString()})}function notify(text){toast=text;render();setTimeout(()=>{toast='';render()},3500)}
const names={map:'Map',opportunities:'Opportunities',expenses:'Expenses',dashboard:'Overview',customers:'Customers',quotes:'Quotations',jobs:'Jobs',tasks:'Tasks',settings:'Settings'};const icons={map:'⌖',opportunities:'◎',expenses:'€',dashboard:'⌂',customers:'♧',quotes:'▤',jobs:'▣',tasks:'✓',settings:'☷'};
async function renderLegacy(){prefs={...prefs,...(await get('settings','business')||{})};document.documentElement.style.setProperty('--brand-accent',prefs.accent);const data=Object.fromEntries(await Promise.all(STORES.map(async s=>[s,await all(s)])));const nav=Object.keys(names).map(k=>`<button class="nav ${tab===k?'active':''}" data-tab="${k}">${icons[k]} &nbsp; ${names[k]}</button>`).join('');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${esc(prefs.company)} <small style="font-size:10px;color:#a4bdc8">LITE</small></div>${nav}</aside><div class="main"><header class="top"><strong>${names[tab]}</strong><span class="muted sub">Offline-first · Data stays on this device</span></header><main class="content">${toast?`<div class="notice" role="status">${esc(toast)}</div>`:''}${view(data)}</main><nav class="mobilebar">${Object.keys(names).map(k=>`<button data-tab="${k}" class="${tab===k?'active':''}"><span class="navicon" aria-hidden="true">${icons[k]}</span><span>${names[k]}</span></button>`).join('')}</nav></div></div>${modal?formModal(data):''}`;if(tab==='map')setTimeout(()=>initializeMap(data),0);}
function view(d){if(tab==='map')return mapView(d);if(tab==='dashboard'){
const pending=d.quotes.filter(x=>x.status==='Sent'),open=d.jobs.filter(x=>x.status!=='Completed'),due=d.tasks.filter(x=>x.status!=='Done'&&x.due<=today());
const total=d.quotes.reduce((a,x)=>a+Number(x.amount||0),0),accepted=d.quotes.filter(x=>x.status==='Accepted').reduce((a,x)=>a+Number(x.amount||0),0);
const statuses=['Draft','Sent','Accepted','Declined'];
const pipeline=statuses.map(st=>{const q=d.quotes.filter(x=>x.status===st),sum=q.reduce((a,x)=>a+Number(x.amount||0),0);return `<div class="stage"><div class="stagehead"><strong>${st}</strong><span>${q.length} quotes</span></div><strong class="stagevalue">${euro(sum)}</strong><div class="stagebar"><span style="width:${total?Math.min(100,sum/total*100):0}%"></span></div></div>`}).join('');
const financeChart=buildFinanceChartSvg(getFinanceSeries(d,financeState.period),financeState.metric,financeState.period);
const statIcons=[tfNavIcons.dashboard,tfNavIcons.opportunities,tfNavIcons.map,tfNavIcons.settings];
const stats=[['Customers',d.customers.length],['Quotations',d.quotes.length],['Active jobs',open.length],['Tasks due',due.length]];
return `<section class="tf-home">
<header class="tf-home-head"><div class="tf-home-brand"><span class="tf-home-symbol">T<span>▪</span></span><span>TRADEFLOW</span></div><button class="tf-home-alert" type="button" data-tab="tasks" aria-label="View tasks">${tfNavIcons.settings}</button></header>
<div class="tf-home-intro"><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}.</h1><p>Your business at a glance.</p></div>
<div class="tf-home-stats">${stats.map(([label,value],i)=>`<button type="button" class="tf-home-stat" data-tab="${['customers','quotes','jobs','tasks'][i]}"><span class="tf-stat-icon">${statIcons[i]}</span><strong>${value}</strong><span>${label}</span></button>`).join('')}</div>
<section class="tf-home-finance"><div class="tf-home-charthead"><div><span class="tf-home-kicker">${esc(financeState.metric)}</span><strong>${euro(financeState.metric==='Quoted Pipeline'?total:getFinanceSeries(d,financeState.period).points.reduce((sum,x)=>sum+Number(x[({Revenue:'revenue',Expenses:'expenses',Profit:'profit'}[financeState.metric]||'revenue')]||0),0))}</strong></div><span class="tf-home-period">${esc(financeState.period)}</span></div>
<div class="tf-home-chart">${financeChart}</div><div class="tf-home-controls"><div class="segmented">${['1W','1M','3M','6M','1Y','All'].map(period=>`<button class="segment ${financeState.period===period?'active':''}" data-finance-period="${period}">${period}</button>`).join('')}</div><div class="segmented">${['Revenue','Expenses','Profit','Quoted Pipeline'].map(metric=>`<button class="segment ${financeState.metric===metric?'active':''}" data-finance-metric="${metric}">${metric}</button>`).join('')}</div></div><p class="tf-home-disclaimer">Financial figures use recorded transactions. Accepted quotes are not revenue.</p></section>
<div class="tf-home-shortcuts"><button class="btn secondary small" data-tab="opportunities">Explore opportunities →</button><button class="btn secondary small" data-tab="quotes">Manage quotes →</button></div>
<details class="tf-home-details"><summary>Quotation portfolio · ${euro(total)}</summary><p>${d.quotes.length} quotations · ${euro(accepted)} accepted</p><div class="stagegrid">${pipeline}</div></details>
${portfolio(d)}
<section class="panel"><div class="panelhead"><h3>Recent activity</h3></div>${d.events.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(x=>`<p class="sub">${esc(x.text)} <span class="muted">· ${new Date(x.date).toLocaleDateString()}</span></p>`).join('')||'<p class="muted">No activity yet</p>'}</section>
</section>`}
if(tab==='opportunities')return opportunityView(d);if(tab==='settings')return `<section class='panel'><h3>Personalize your business</h3><form id='settingsForm'><label class='field'>Business name<input class='input' name='company' required maxlength='70' value='${esc(prefs.company)}'></label><label class='field'>Accent color<input class='input' type='color' name='accent' value='${esc(prefs.accent)}'></label><label class='field'>Trade categories (one per line)<textarea class='input' name='categories' rows='5'>${esc(prefs.categories.join('\n'))}</textarea></label><button class='btn' type='submit'>Save branding</button></form></section><div class='panel'><h3>Backup and restore</h3><p class='muted'>Export all records as a JSON file. Store it securely. Restoring replaces records on this device.</p><div class='toolbar'><button class='btn' data-action='export'>Export backup</button><label class='btn secondary' for='restoreFile'>Restore backup</label><input id='restoreFile' type='file' accept='application/json,.json' hidden></div><div class='notice warning'>No cloud sync or encryption is provided. Use fictional data for demonstrations.</div></div>`;if(tab==='legacySettings')return `<div class="panel"><h3>Backup and restore</h3><p class="muted">Export all records as a JSON file. Store it somewhere secure. Restoring replaces all records on this device.</p><div class="toolbar"><button class="btn" data-action="export">Export backup</button><label class="btn secondary" for="restoreFile">Restore backup</label><input id="restoreFile" type="file" accept="application/json,.json" hidden></div><div class="notice warning">No account, cloud sync or encryption at rest is provided. Anyone with access to this browser profile may be able to access its records. Use fictional records for your initial demo.</div></div>`;
const conf={expenses:{fields:['title','category','amount','date'],headers:['Expense','Trade','Amount','Date'],title:'expense'},customers:{fields:['name','phone','email','address'],headers:['Customer','Phone','Email','Address'],title:'customer'},quotes:{fields:['customerId','title','category','amount','status','sentDate'],headers:['Customer','Quote','Trade','Value','Status','Sent'],title:'quotation'},jobs:{fields:['customerId','title','category','status','date'],headers:['Customer','Job','Trade','Status','Scheduled'],title:'job'},tasks:{fields:['title','customerId','due','status'],headers:['Task','Customer','Due','Status'],title:'task'}}[tab];let rows=d[tab].filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(query.toLowerCase()))||d.customers.some(c=>c.id===x.customerId&&c.name.toLowerCase().includes(query.toLowerCase())));const cust=id=>d.customers.find(c=>c.id===id)?.name||'—';const cell=(x,f)=>f==='customerId'?cust(x[f]):f==='amount'?euro(x[f]):f==='status'?`<span class="pill">${esc(x[f])}</span>`:esc(x[f]||'—');return `<div class="toolbar"><input class="input search" id="search" placeholder="Search ${tab}..." value="${esc(query)}" aria-label="Search records"><button class="btn" data-action="new">+ New ${conf.title}</button></div><section class="panel"><div class="panelhead"><h3>${names[tab]} <span class="muted sub">(${rows.length})</span></h3></div>${rows.length?`<div class="tablewrap"><table><thead><tr>${conf.headers.map(h=>`<th>${h}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr>${conf.fields.map(f=>`<td>${cell(x,f)}</td>`).join('')}<td><div class="rowactions"><button class="btn small secondary" data-edit="${x.id}">Edit</button><button class="btn small danger" data-delete="${x.id}">Delete</button>${tab==='quotes'&&x.status==='Accepted'&&!d.jobs.some(j=>j.quoteId===x.id)?`<button class="btn small" data-convert="${x.id}">Create job</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No records found. Add your first ${conf.title}.</div>`}</section>`}
function portfolio(d){
const cats=[...new Set([...prefs.categories,...d.quotes.map(x=>x.category||'Other'),...d.expenses.map(x=>x.category||'Other')])];
const stats=cats.map(c=>({c,quotes:d.quotes.filter(x=>(x.category||'Other')===c),expenses:d.expenses.filter(x=>(x.category||'Other')===c)}));
return `<section class="panel"><div class="panelhead"><h3>Trade performance</h3><span class="muted sub">By category</span></div><div class="tradegrid">${stats.map(x=>{const quoted=x.quotes.reduce((a,q)=>a+Number(q.amount||0),0),accepted=x.quotes.filter(q=>q.status==='Accepted').reduce((a,q)=>a+Number(q.amount||0),0),cost=x.expenses.reduce((a,e)=>a+Number(e.amount||0),0);return `<div class="tradebox"><div class="tradehead"><strong>${esc(x.c)}</strong><span>↗</span></div><div class="tradeamount">${euro(quoted)}</div><span class="muted sub">${x.quotes.length} quotes</span><div class="tradefoot"><span>Accepted <b>${euro(accepted)}</b></span><span>Expenses <b>${euro(cost)}</b></span></div></div>`}).join('')}</div><p class="muted sub">Quoted and accepted amounts are not payments received. Expenses are manually entered.</p></section>`}
function formModal(d){const obj=modal.id?d[tab].find(x=>x.id===modal.id)||{}:{};const customers=d.customers.map(c=>`<option value="${esc(c.id)}" ${obj.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('');const defs={expenses:[['title','Expense description','text',true],['category','Trade category','category',true],['amount','Amount (€)','number',true],['date','Date','date',true]],customers:[['name','Customer name','text',true],['phone','Phone','tel'],['email','Email','email'],['address','Address','text']],quotes:[['customerId','Customer','customer',true],['title','Description','text',true],['category','Trade category','category',true],['amount','Estimated value (€)','number',true],['status','Status','select:Draft,Sent,Accepted,Declined'],['sentDate','Date sent','date']],jobs:[['customerId','Customer','customer',true],['title','Job description','text',true],['category','Trade category','category',true],['status','Status','select:Planned,In Progress,Completed'],['date','Scheduled date','date']],tasks:[['title','Task','text',true],['customerId','Customer','customer'],['due','Due date','date',true],['status','Status','select:Open,Done']]}[tab];return `<div class="dialog"><form class="modal" id="recordForm"><div class="modalhead"><h2>${modal.id?'Edit':'New'} ${tab.slice(0,-1)}</h2><button class="btn secondary small" type="button" data-action="close">✕</button></div><div class="formgrid">${defs.map(([key,label,type,required])=>`<label class="field">${label}${type==='category'?`<select class="input" name="${key}">${prefs.categories.map(v=>`<option value="${esc(v)}" ${obj[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='customer'?`<select class="input" name="${key}" ${required?'required':''}><option value="">Choose customer</option>${customers}</select>`:type.startsWith('select:')?`<select class="input" name="${key}">${type.slice(7).split(',').map(v=>`<option ${obj[key]===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input class="input" name="${key}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} value="${esc(obj[key]??(type==='date'&&key==='due'?today():''))}">`}</label>`).join('')}</div><div class="actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn" type="submit">Save record</button></div></form></div>`}
async function saveForm(form){const f=Object.fromEntries(new FormData(form));if(tab==='customers'){f.email=f.email.trim().toLowerCase();const existing=(await all('customers')).find(c=>c.id!==modal.id&&((f.email&&c.email===f.email)||(f.phone&&c.phone===f.phone)));if(existing&&!confirm('A customer already has this email or phone. Save anyway?'))return}const id=modal.id||uid(),old=modal.id?await get(tab,id):{};await put(tab,{...old,...f,id,updatedAt:new Date().toISOString()});await event(`${modal.id?'Updated':'Created'} ${tab.slice(0,-1)}: ${f.name||f.title}`);if(tab==='quotes'&&f.status==='Sent'&&old.status!=='Sent'){const tasks=await all('tasks');if(!tasks.some(t=>t.quoteId===id)){await put('tasks',{id:uid(),title:`Follow up quote: ${f.title}`,customerId:f.customerId,due:new Date(Date.now()+3*86400000).toISOString().slice(0,10),status:'Open',quoteId:id});await event('Created quote follow-up task')}}modal=null;query='';notify('Record saved')}
async function exportData(){const data={format:'tradeflow-lite',version:4,exportedAt:new Date().toISOString(),stores:Object.fromEntries(await Promise.all(STORES.map(async s=>[s,await all(s)])))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`tradeflow-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function restore(file){let data;try{data=JSON.parse(await file.text());if(data.format!=='tradeflow-lite'||![1,2,3,4].includes(data.version)||!data.stores||!STORES.every(s=>Array.isArray(data.stores[s]||((data.version<4||s==='pins')?[]:null))&&(data.stores[s]||[]).every(x=>x&&typeof x.id==='string')))throw Error('Invalid backup');if(!confirm('Replace ALL existing local records with this backup? This cannot be undone.'))return;const t=db.transaction(STORES,'readwrite');for(const s of STORES){const st=t.objectStore(s);st.clear();for(const item of (data.stores[s]||[]))st.put(item)}await new Promise((resolve,reject)=>{t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)});notify('Backup restored')}catch(e){alert(`Restore failed: ${e.message}`)}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-tab],[data-action],[data-edit],[data-delete],[data-convert]');if(!el)return;if(el.dataset.action==='mapFilters'){const controls=document.getElementById('tfMapControls');if(controls)controls.hidden=!controls.hidden;return}if(el.dataset.action==='mapMode'){prefs.mapMode=el.dataset.mode;await put('settings',{id:'business',...prefs});const d=Object.fromEntries(await Promise.all(STORES.map(async store=>[store,await all(store)])));initializeMap(d);return}if(el.dataset.action==='mapSearch'){searchMapAddress();return}if(el.dataset.action==='mapHome'){setMapHome();return}if(el.dataset.action==='mapPinDelete'){if(confirm('Delete this saved map pin?')){await del('pins',el.dataset.id);render()}return}if(el.dataset.action==='mapPinView'){focusMapPin(el.dataset.id);return}if(el.dataset.action==='importOpportunities'){document.getElementById('opportunityFile')?.click();return}if(el.dataset.action==='exportOpportunities'){exportOpportunities();return}if(el.dataset.action==='opportunityStatus'){const r=await get('opportunities',el.dataset.id);if(r){r.status=el.dataset.status;await put('opportunities',r);notify('Opportunity updated')}return}if(el.dataset.tab){tab=el.dataset.tab;query='';modal=null;render()}else if(el.dataset.action==='new'){if(['quotes','jobs','tasks'].includes(tab)&&(await all('customers')).length===0){alert('Create a customer first.');tab='customers';render();return}modal={};render()}else if(el.dataset.action==='close'){modal=null;render()}else if(el.dataset.action==='export')exportData();else if(el.dataset.edit){modal={id:el.dataset.edit};render()}else if(el.dataset.delete){if(!confirm('Delete this record? This cannot be undone.'))return;const id=el.dataset.delete;if(tab==='customers'){const refs=await Promise.all(['quotes','jobs','tasks'].map(all));if(refs.some(a=>a.some(x=>x.customerId===id))){alert('This customer has linked records. Remove or reassign those first.');return}}await del(tab,id);await event(`Deleted ${tab.slice(0,-1)}`);notify('Record deleted')}else if(el.dataset.convert){const q=await get('quotes',el.dataset.convert);if(q?.status!=='Accepted')return;const jobs=await all('jobs');if(jobs.some(j=>j.quoteId===q.id))return;await put('jobs',{id:uid(),quoteId:q.id,customerId:q.customerId,title:q.title,category:q.category||'Other',status:'Planned',date:''});await event(`Created job from accepted quotation: ${q.title}`);notify('Job created')}});
document.addEventListener('submit',e=>{if(e.target.id==='settingsForm'){e.preventDefault();const f=new FormData(e.target),categories=String(f.get('categories')||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean).slice(0,30);if(!categories.length)return alert('Add at least one category');prefs={...prefs,company:String(f.get('company')).trim(),accent:String(f.get('accent')),categories};put('settings',{id:'business',...prefs}).then(()=>notify('Branding saved'));return}if(e.target.id==='recordForm'){e.preventDefault();saveForm(e.target).catch(err=>alert(err.message))}});document.addEventListener('input',e=>{if(e.target.id==='mapAddress'){showLocalMapSuggestions(e.target.value);return}if(e.target.id==='opportunitySearch'){opSearch=e.target.value;render().then(()=>{const i=$('#opportunitySearch');i?.focus();i?.setSelectionRange(opSearch.length,opSearch.length)});return}if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render().then(()=>{const i=$('#search');i?.focus();i?.setSelectionRange(pos,pos)})}});document.addEventListener('change',e=>{if(e.target.id==='restoreFile'&&e.target.files[0])restore(e.target.files[0]);if(e.target.id==='opportunityFile'&&e.target.files[0])importOpportunities(e.target.files[0]).catch(err=>alert(err.message))});

let opSearch='';
const opFields=['record_id','source_record_id','project_name','trade','opportunity_type','project_description','city','region','latitude','longitude','source_url','source_date','discovered_at','verified_at','evidence_status','status','organization_name','contact_url','evidence_notes'];
function parseCSV(text){if(text.charCodeAt(0)===0xFEFF)text=text.slice(1);const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('Unclosed CSV quotation mark');if(field||row.length){row.push(field);rows.push(row)}return rows}
function csvCell(v){const t=String(v??'');return /[",\r\n]/.test(t)?'"'+t.replace(/"/g,'""')+'"':t}
function downloadFile(filename,content,mime){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:mime}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function exportOpportunities(){const data=await all('opportunities');downloadFile('tradeflow-opportunities-'+today()+'.csv',[opFields.join(','),...data.map(r=>opFields.map(f=>csvCell(r[f])).join(','))].join('\r\n'),'text/csv')}
function convertE06Audit(rows){const headers=rows[0].map(x=>x.trim().toLowerCase());const col=(row,name)=>row[headers.indexOf(name)]||'';const converted=[opFields];for(const row of rows.slice(1)){const qc=col(row,'qc_decision').toUpperCase(),kind=col(row,'submitted_classification').toLowerCase(),location=col(row,'location'),id=col(row,'record_id');const record={record_id:id,source_record_id:id,project_name:col(row,'entity_or_project'),trade:'Electrical',opportunity_type:kind.includes('potential')?'potential_opportunity':kind.includes('business')?'business_prospect':'project_signal',project_description:location+'; '+col(row,'reviewer_notes'),city:location,region:'Texas',latitude:'',longitude:'',source_url:col(row,'original_source_url'),source_date:col(row,'source_date')||col(row,'research_date'),discovered_at:col(row,'research_date'),verified_at:col(row,'research_date'),evidence_status:qc==='UNRESOLVED'?'unresolved':'source_supported',status:'New',organization_name:col(row,'entity_or_project'),contact_url:'',evidence_notes:'E06 QC: '+qc+'; '+col(row,'source_verification')};converted.push(opFields.map(f=>record[f]||''))}return converted}
async function importOpportunities(file){if(file.size>5*1024*1024)throw Error('File exceeds 5 MB');const rows=parseCSV(await file.text());if(rows.length<2)throw Error('CSV must contain a header and at least one record');if(rows.length>5001)throw Error('Import a maximum of 5,000 records at a time');if(rows[0].map(v=>v.trim().toLowerCase()).includes('qc_decision')){const converted=convertE06Audit(rows);rows.splice(0,rows.length,...converted)}const headers=rows.shift().map(v=>v.trim().toLowerCase());for(const f of ['record_id','project_name','opportunity_type','source_url'])if(!headers.includes(f))throw Error('Missing required column: '+f);const allowedTypes=['project_signal','potential_opportunity','verified_request','business_prospect'];const existing=await all('opportunities'),ids=new Set(existing.map(x=>x.id)),sources=new Set(existing.filter(x=>x.source_record_id).map(x=>x.source_url+'|'+x.source_record_id));let added=0,duplicates=0,rejected=0;const staged=[];const validUrl=u=>{try{const v=new URL(u);return ['https:','http:'].includes(v.protocol)}catch{return false}};
for(const cells of rows){if(cells.length!==headers.length){rejected++;continue}const raw=Object.fromEntries(headers.map((h,i)=>[h,(cells[i]||'').trim()]));const id=raw.record_id,lat=raw.latitude?Number(raw.latitude):null,lon=raw.longitude?Number(raw.longitude):null;if(!id||id.length>150||!raw.project_name||!['verified','source_supported','unresolved'].includes(raw.evidence_status)||!allowedTypes.includes(raw.opportunity_type)||!validUrl(raw.source_url)||!raw.source_url.startsWith('https://')||!raw.source_date||!raw.verified_at||(raw.latitude&&(!Number.isFinite(lat)||Math.abs(lat)>90))||(raw.longitude&&(!Number.isFinite(lon)||Math.abs(lon)>180))||(raw.latitude&&!raw.longitude)||(!raw.latitude&&raw.longitude)){rejected++;continue}const sourceKey=raw.source_url+'|'+raw.source_record_id;if(ids.has(id)||(raw.source_record_id&&sources.has(sourceKey))){duplicates++;continue}ids.add(id);if(raw.source_record_id)sources.add(sourceKey);staged.push({...Object.fromEntries(opFields.map(f=>[f,raw[f]||''])),id,latitude:lat,longitude:lon,trade:raw.trade||'Electrical',evidence_status:raw.evidence_status||'unreviewed',status:'New',imported_at:new Date().toISOString()})}
if(!staged.length){alert(`Nothing imported. Duplicates: ${duplicates}; invalid: ${rejected}.`);return}if(!confirm(`Import ${staged.length} records? ${duplicates} duplicates and ${rejected} invalid rows will be skipped.`))return;const transaction=db.transaction('opportunities','readwrite');for(const r of staged)transaction.objectStore('opportunities').put(r);await new Promise((resolve,reject)=>{transaction.oncomplete=resolve;transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error)});added=staged.length;alert(`Imported ${added} records. Skipped ${duplicates} duplicates and ${rejected} invalid rows.`);render()}
function opportunityView(d){const data=d.opportunities||[],q=opSearch.toLowerCase(),filtered=data.filter(x=>[x.project_name,x.city,x.region,x.project_description,x.organization_name,x.opportunity_type].join(' ').toLowerCase().includes(q));const located=filtered.filter(x=>x.evidence_status==='verified'&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude));const latMin=located.length?Math.min(...located.map(x=>x.latitude)):0,latMax=located.length?Math.max(...located.map(x=>x.latitude)):1,lonMin=located.length?Math.min(...located.map(x=>x.longitude)):0,lonMax=located.length?Math.max(...located.map(x=>x.longitude)):1;const dots=located.slice(0,300).map(x=>{const cx=20+360*(x.longitude-lonMin)/(lonMax-lonMin||1),cy=190-170*(x.latitude-latMin)/(latMax-latMin||1);return `<circle cx="${cx}" cy="${cy}" r="5" fill="${x.opportunity_type==='verified_request'?'#1d8b70':x.opportunity_type==='potential_opportunity'?'#e4a12d':'#448bb8'}"><title>${esc(x.project_name)} · ${esc(x.city)}</title></circle>`}).join('');return `<section class="panel"><div class="panelhead"><h3>Opportunity Explorer</h3><span class="muted sub">Offline · Local records</span></div><p class="muted">Import sourced electrical project research. Project signals are not confirmed customer requests.</p><div class="toolbar"><button class="btn" data-action="importOpportunities">Import CSV / E06 Audit</button><button class="btn secondary" data-action="exportOpportunities">Export CSV</button><input id="opportunityFile" type="file" accept=".csv,text/csv" hidden></div><div class="cards">${[['Records',data.length],['Review only',data.filter(x=>x.evidence_status!=='verified').length],['Verified requests',data.filter(x=>x.opportunity_type==='verified_request').length],['Mapped',data.filter(x=>x.evidence_status==='verified'&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude)).length]].map(([l,v])=>`<div class="card"><div class="muted sub">${l}</div><div class="num">${v}</div></div>`).join('')}</div></section><section class="panel"><h3>Location overview</h3><p class="muted sub">Relative-coordinate plot of imported records, not a street map. Pins show up to 300 matching records. No data leaves your device.</p><svg viewBox="0 0 400 220" role="img" aria-label="Relative location plot" style="width:100%;background:#eef4f6;border-radius:12px"><path d="M20 20V190H380" stroke="#b7c8cf" stroke-width="1.5" fill="none"/>${dots}</svg><p class="muted sub">Blue: project signal · Gold: potential opportunity · Green: verified request</p></section><section class="panel"><div class="panelhead"><h3>Research records (${filtered.length})</h3></div><input class="input" id="opportunitySearch" placeholder="Search project, city or company" value="${esc(opSearch)}"><div class="oplist">${filtered.slice(0,150).map(x=>`<article class="opitem"><div class="panelhead"><strong>${esc(x.project_name)}</strong><span class="pill">${esc(x.opportunity_type.replaceAll('_',' '))}</span></div><p class="muted sub">${esc([x.city,x.region].filter(Boolean).join(', '))} · ${esc(x.trade)} · ${esc(x.source_date||'Undated')}</p><p class="sub">${esc(x.project_description||'No project description')}</p><p class="sub">Evidence: ${esc(x.evidence_status)} · ${x.evidence_status==='verified'?'Research record — demand not guaranteed':'REVIEW ONLY · Not approved for distribution'} · Workflow: ${esc(x.status)}</p><div class="toolbar"><a class="btn secondary small" target="_blank" rel="noopener noreferrer" href="${esc(x.source_url)}">Source ↗</a>${x.contact_url&&/^https:\/\//.test(x.contact_url)?`<a class="btn secondary small" target="_blank" rel="noopener noreferrer" href="${esc(x.contact_url)}">Business ↗</a>`:''}<button class="btn small" data-action="opportunityStatus" data-id="${esc(x.id)}" data-status="${x.status==='Saved'?'New':'Saved'}">${x.status==='Saved'?'Unsave':'Save'}</button></div></article>`).join('')||'<p class="muted">No records yet. Import the CSV template from the research kit.</p>'}</div>${filtered.length>150?'<p class="muted sub">Showing first 150 matches. Narrow your search to find more.</p>':''}</section>`}

