const mapCenter=()=>{const lat=Number(prefs.homeLat),lon=Number(prefs.homeLon),saved=prefs.homeLat!==undefined&&prefs.homeLat!==''&&prefs.homeLon!==undefined&&prefs.homeLon!==''&&Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180;return saved?{lat,lon}:{lat:30.2672,lon:-97.7431}};
function mapView(d){const pins=d.pins||[],located=(d.opportunities||[]).filter(x=>x.evidence_status==='verified'&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude));return `<section class="tf-map-screen" aria-label="TradeFlow tactical map"><div id="territoryMap" class="territory-map" role="region" aria-label="Interactive street map"></div><div class="tf-map-top"><div class="tf-map-brand"><span class="tf-brand-t">T<span>▪</span></span><span>TRADEFLOW</span><button class="tf-map-filter" type="button" data-action="mapFilters" aria-label="Map appearance and filters">☷</button></div><div class="tf-map-search-wrap"><div class="tf-map-search"><span aria-hidden="true">⌕</span><input id="mapAddress" autocomplete="off" placeholder="Search places, addresses, projects..." aria-label="Search map"><button type="button" data-action="mapSearch" aria-label="Search address">↗</button></div><div id="tfMapSuggestions" class="tf-map-suggestions" role="listbox" hidden></div></div><div id="tfMapControls" class="tf-map-controls" hidden><div class="tf-map-modes" role="group" aria-label="Map style"><button type="button" class="btn small" data-action="mapMode" data-mode="intelligence">Intelligence</button><button type="button" class="btn secondary small" data-action="mapMode" data-mode="standard">Standard</button><button type="button" class="btn secondary small" data-action="mapMode" data-mode="terrain">Terrain / 3D</button></div><button class="btn secondary small" data-action="mapHome">Set current view as home</button><p class="muted sub">Only verified-coordinate research records are mapped. No inferred project boundaries.</p></div></div><div class="tf-map-footer"><span id="mapStatus" role="status">Loading map…</span><span>${pins.length} saved · ${located.length} research locations</span></div></section>`}
async function loadMapLibre(){if(window.maplibregl)return;await new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css';document.head.appendChild(css);const script=document.createElement('script');script.src='https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.js';script.onload=resolve;script.onerror=()=>reject(Error('Map library could not load. Internet is required for first use.'));document.head.appendChild(script)})}
async function initializeMap(d){if(tab!=='map'||!document.getElementById('territoryMap'))return;try{if(liveMap){const c=liveMap.getCenter();mapLastView={center:[c.lng,c.lat],zoom:liveMap.getZoom()};liveMap.remove();liveMap=null}mapMarkers=[];await loadMapLibre();if(tab!=='map')return;const center=mapLastView||{center:[mapCenter().lon,mapCenter().lat],zoom:11};liveMap=new maplibregl.Map({container:'territoryMap',center:center.center,zoom:center.zoom,style:prefs.mapMode==='standard'?'https://tiles.openfreemap.org/styles/liberty':'https://tiles.openfreemap.org/styles/dark',attributionControl:true});liveMap.addControl(new maplibregl.NavigationControl({showCompass:true}),'top-right');if(prefs.mapMode==='terrain')liveMap.setPitch(55);document.querySelectorAll('[data-action="mapMode"]').forEach(b=>{const active=b.dataset.mode===(prefs.mapMode||'intelligence');b.classList.toggle('secondary',!active)});liveMap.addControl(new maplibregl.ScaleControl({maxWidth:100,unit:'metric'}),'bottom-left');const status=document.getElementById('mapStatus');if(status)status.textContent='Loading street map…';liveMap.on('load',()=>{const current=document.getElementById('mapStatus');if(current)current.textContent=`${mapMarkers.length} locations plotted. Tiles require an internet connection.`});liveMap.on('error',()=>{const current=document.getElementById('mapStatus');if(current)current.textContent='Street map tiles are unavailable. Check your connection; saved records remain available locally.'});liveMap.on('load',()=>{if(prefs.mapMode!=='intelligence')return;const records=(d.opportunities||[]).filter(x=>x.evidence_status==='verified'&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude)&&Math.abs(x.latitude)<=90&&Math.abs(x.longitude)<=180);const features=records.map(x=>({type:'Feature',geometry:{type:'Point',coordinates:[x.longitude,x.latitude]},properties:{id:String(x.id),name:String(x.project_name||'Opportunity'),kind:String(x.opportunity_type||'project_signal')}}));if(!features.length)return;liveMap.addSource('tf-intelligence',{type:'geojson',data:{type:'FeatureCollection',features},cluster:true,clusterRadius:55,clusterMaxZoom:13});liveMap.addLayer({id:'tf-zone-glow',type:'circle',source:'tf-intelligence',filter:['has','point_count'],paint:{'circle-color':prefs.accent||'#22c0b3','circle-radius':['step',['get','point_count'],24,5,32,20,44],'circle-opacity':0.13,'circle-blur':0.55}});liveMap.addLayer({id:'tf-clusters',type:'circle',source:'tf-intelligence',filter:['has','point_count'],paint:{'circle-color':'#102b3c','circle-stroke-color':prefs.accent||'#22c0b3','circle-stroke-width':2,'circle-radius':['step',['get','point_count'],17,5,23,20,30]}});liveMap.addLayer({id:'tf-cluster-count',type:'symbol',source:'tf-intelligence',filter:['has','point_count'],layout:{'text-field':['get','point_count_abbreviated'],'text-size':13},paint:{'text-color':'#e8ffff'}});liveMap.on('click','tf-clusters',e=>{const f=e.features&&e.features[0];if(!f)return;liveMap.easeTo({center:f.geometry.coordinates,zoom:Math.min(liveMap.getZoom()+2,17)});});liveMap.on('mouseenter','tf-clusters',()=>{liveMap.getCanvas().style.cursor='pointer'});liveMap.on('mouseleave','tf-clusters',()=>{liveMap.getCanvas().style.cursor=''})});liveMap.on('click',async e=>{const target=e.originalEvent&&e.originalEvent.target;if(target&&target.closest&&target.closest('.maplibregl-marker,.maplibregl-popup'))return;if(e.originalEvent&&e.originalEvent.detail>1)return;const now=Date.now();if(now-lastMapTap<350)return;lastMapTap=now;const request=++mapClickRequest,lat=e.lngLat.lat,longitude=e.lngLat.lng,address=await reverseMapAddress(lat,longitude);if(request!==mapClickRequest)return;showTemporaryMapLocation(liveMap,d,lat,longitude,address||'Address unavailable')});const opportunities=(d.opportunities||[]).filter(x=>x.evidence_status==='verified'&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude)&&Math.abs(x.latitude)<=90&&Math.abs(x.longitude)<=180);const locations=[...(d.pins||[]).map(x=>({...x,mapKind:'pin'})),...opportunities.map(x=>({...x,longitude:x.longitude,mapKind:'opportunity'}))];for(const customer of d.customers||[]){let point=parseSavedCoordinates(customer.coordinates);if(!point&&customer.address){const result=await geocodeMapAddress(customer.address);if(result)point={latitude:result.lat,longitude:result.lon}}if(point)locations.push({id:customer.id,title:customer.name||'Customer',address:customer.address,latitude:point.latitude,longitude:point.longitude,mapKind:'customer'})}for(const job of d.jobs||[]){const point=parseSavedCoordinates(job.coordinates);if(point)locations.push({id:job.id,title:job.title||'Job',address:job.address,latitude:point.latitude,longitude:point.longitude,mapKind:'job'})}mapSuggestionRecords=locations.filter(x=>Number.isFinite(x.latitude)&&Number.isFinite(x.longitude)).map(x=>({label:x.title||x.project_name||x.name||x.address||'Location',type:x.mapKind,latitude:x.latitude,longitude:x.longitude}));for(const x of locations.slice(0,600)){if(!Number.isFinite(x.latitude)||!Number.isFinite(x.longitude)||Math.abs(x.latitude)>90||Math.abs(x.longitude)>180)continue;const color=x.mapKind==='opportunity'?(x.opportunity_type==='verified_request'?'#1d8b70':'#d49a34'):'#22c0b3',markerEl=tradeFlowMarker(color),title=x.title||x.project_name||'Map location',detail=x.address||x.city||x.opportunity_type||'Saved location',marker=new maplibregl.Marker({element:markerEl,anchor:'bottom'}).setLngLat([x.longitude,x.latitude]).addTo(liveMap);markerEl.addEventListener('click',e=>{e.stopPropagation();showExistingMapLocation(x)});mapMarkers.push(marker)}}catch(err){const status=document.getElementById('mapStatus');if(status)status.textContent=`Map unavailable: ${err.message}. Your records remain available locally.`}}
async function searchMapAddressLegacy(){const q=document.getElementById('mapAddress')?.value.trim();if(!q)return;const status=document.getElementById('mapStatus');if(status)status.textContent='Searching…';try{const response=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(q),{headers:{'Accept':'application/json'}});if(!response.ok)throw Error('Search unavailable');const results=await response.json();if(!results.length)throw Error('No matching location');liveMap?.flyTo({center:[Number(results[0].lon),Number(results[0].lat)],zoom:14});if(status)status.textContent='Location found. Tap the map to save a pin.'}catch(err){if(status)status.textContent=err.message}}
