function openTradeFlowSheet(html){closeTradeFlowSheet();const shade=document.createElement('div');shade.id='tfSheetShade';shade.className='tf-sheet-shade';shade.addEventListener('click',closeTradeFlowSheet);const sheet=document.createElement('section');sheet.id='tfLocationSheet';sheet.className='tf-location-sheet';sheet.setAttribute('role','dialog');sheet.setAttribute('aria-label','Location details');sheet.innerHTML='<div class="tf-sheet-grip"></div><button class="tf-sheet-close" type="button" aria-label="Close location details">×</button>'+html;document.body.append(shade,sheet);sheet.querySelector('.tf-sheet-close').addEventListener('click',closeTradeFlowSheet)}
function showTemporaryMapLocation(map,data,latitude,longitude,address){if(pendingMapMarker)pendingMapMarker.remove();const element=tradeFlowMarker('#35dce4');element.classList.add('tradeflow-map-marker-temp');pendingMapMarker=new maplibregl.Marker({element,anchor:'bottom'}).setLngLat([longitude,latitude]).addTo(map);const customers=(data.customers||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.name||'Customer')}</option>`).join(''),jobs=(data.jobs||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.title||'Job')}</option>`).join('');const attrs=`data-lat="${latitude}" data-lng="${longitude}" data-address="${esc(address||'')}"`;openTradeFlowSheet(`<div class="tf-sheet-eyebrow">TRADEFLOW · LOCATION INTELLIGENCE</div><h2>Selected location</h2><p class="tf-sheet-address">${esc(address||'Address unavailable')}</p><p class="muted sub">${latitude.toFixed(5)}, ${longitude.toFixed(5)} · Approximate address</p><div class="tf-sheet-actions"><a class="btn small" href="https://www.openstreetmap.org/directions?to=${latitude}%2C${longitude}" target="_blank" rel="noopener">Directions ↗</a><button class="btn secondary small" data-map-action="save" ${attrs}>Save</button><button class="btn secondary small" data-map-action="opportunity" ${attrs}>Create opportunity</button></div><details class="tf-sheet-more"><summary>Link records & additional actions</summary><label>Customer<select class="input" data-link-customer><option value="">Select customer</option>${customers}</select></label><button class="btn secondary small" data-map-action="customer" ${attrs}>Link customer</button><label>Job<select class="input" data-link-job><option value="">Select job</option>${jobs}</select></label><button class="btn secondary small" data-map-action="job" ${attrs}>Link job</button></details>`)}
function showExistingMapLocation(record){const name=record.title||record.project_name||record.name||'Location',address=record.address||record.city||'Saved map location',isResearch=record.mapKind==='opportunity';openTradeFlowSheet(`<div class="tf-sheet-eyebrow">TRADEFLOW · ${esc(record.mapKind||'LOCATION')}</div><h2>${esc(name)}</h2><p class="tf-sheet-address">${esc(address)}</p>${isResearch?`<p class="muted sub">Classification: ${esc(record.opportunity_type)} · Evidence: ${esc(record.evidence_status)} · Not a confirmed open bid</p>`:''}<div class="tf-sheet-actions"><a class="btn small" href="https://www.openstreetmap.org/directions?to=${record.latitude}%2C${record.longitude}" target="_blank" rel="noopener">Directions ↗</a>${record.source_url&&/^https:\/\//.test(record.source_url)?`<a class="btn secondary small" href="${esc(record.source_url)}" target="_blank" rel="noopener">View source ↗</a>`:''}</div>`)}
async function handleMapAction(action,metadata){const latitude=Number(metadata.lat),longitude=Number(metadata.lng),coordinates=JSON.stringify({lat:latitude,lng:longitude});if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;try{if(action==='save'){const title=prompt('Name this location','Saved location');if(title===null||!title.trim())return;await put('pins',{id:uid(),title:title.trim().slice(0,120),type:'Manual pin',latitude,longitude,address:metadata.address||'',createdAt:new Date().toISOString()})}else if(action==='opportunity'){const title=prompt('Opportunity name','New opportunity');if(title===null)return;const amount=Number(prompt('Estimated value (€)','0'));await put('quotes',{id:uid(),customerId:'',title:title.trim()||'New opportunity',category:'Other',amount:Number.isFinite(amount)?amount:0,status:'Draft',sentDate:today(),coordinates,...(metadata.address?{address:metadata.address}:{})});await event(`Created opportunity from map: ${title.trim()||'New opportunity'}`)}else if(action==='customer'||action==='job'){const store=action==='customer'?'customers':'jobs',id=action==='customer'?metadata.customerId:metadata.jobId;if(!id){alert(`Choose a ${action} to link first.`);return}const record=await get(store,id);if(!record){alert(`The selected ${action} no longer exists. Refresh and try again.`);return}record.coordinates=coordinates;if(metadata.address)record.address=metadata.address;await put(store,record);await event(`Linked map location to ${action==='customer'?record.name:record.title}`)}else return;closeTradeFlowSheet();if(pendingMapMarker)pendingMapMarker.remove();pendingMapPopup=null;pendingMapMarker=null;notify(action==='save'?'Location saved':action==='opportunity'?'Opportunity created':action==='customer'?'Customer linked':'Job linked')}catch(error){alert(`Unable to complete map action: ${error.message}`)}}
let mapSuggestionRecords=[];
function showLocalMapSuggestions(text){const box=document.getElementById('tfMapSuggestions');if(!box)return;const q=String(text||'').trim().toLowerCase();if(q.length<2){box.hidden=true;return}const matches=mapSuggestionRecords.filter(x=>String(x.label).toLowerCase().includes(q)).slice(0,6);box.innerHTML=matches.map((x,i)=>`<button type="button" role="option" data-map-suggestion="${i}"><span>⌖</span><span>${esc(x.label)}<small>${esc(x.type)} · Saved TradeFlow record</small></span></button>`).join('')+'<button type="button" data-action="mapSearch"><span>⌕</span><span>Search online for “'+esc(text)+'”<small>Full search · internet required</small></span></button>';box.hidden=false;box._matches=matches}
document.addEventListener('click',event=>{const button=event.target.closest('[data-map-suggestion]');if(!button)return;event.stopImmediatePropagation();const box=document.getElementById('tfMapSuggestions'),match=box?._matches?.[Number(button.dataset.mapSuggestion)];if(!match)return;box.hidden=true;document.getElementById('mapAddress').value=match.label;liveMap?.flyTo({center:[match.longitude,match.latitude],zoom:16})});
async function searchMapAddress(){const query=document.getElementById('mapAddress')?.value.trim();if(!query)return;const suggestions=document.getElementById('tfMapSuggestions');if(suggestions)suggestions.hidden=true;const status=document.getElementById('mapStatus');if(status)status.textContent='Searching…';try{const results=await mapNominatim(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q=${encodeURIComponent(query)}`);if(!results.length)throw Error('No matching location');liveMap?.flyTo({center:[Number(results[0].lon),Number(results[0].lat)],zoom:14});if(status)status.textContent='Location found. Tap once to preview a temporary location.'}catch(error){if(status)status.textContent=`${error.message}. Coordinates can still be used by tapping the map.`}}
function getFinanceSeries(data,period='All'){const ranges={'1W':7,'1M':30,'3M':90,'6M':180,'1Y':365,'All':3650},days=ranges[period]||3650,end=new Date();end.setHours(0,0,0,0);const start=new Date(end);start.setDate(end.getDate()-days+1);const buckets=new Map();for(let i=0;i<days;i++){const date=new Date(start);date.setDate(start.getDate()+i);buckets.set(date.toISOString().slice(0,10),{date,revenue:0,expenses:0,profit:0,quoted:0})}const add=(dateValue,key,amount)=>{if(!dateValue)return;const date=new Date(dateValue);if(Number.isNaN(date.getTime()))return;const bucket=buckets.get(date.toISOString().slice(0,10));if(bucket)bucket[key]+=Number.isFinite(Number(amount))?Number(amount):0};for(const expense of data.expenses||[])add(expense.date,'expenses',expense.amount);for(const quote of data.quotes||[])add(quote.sentDate||quote.date,'quoted',quote.amount);const points=Array.from(buckets.values());for(const point of points)point.profit=point.revenue-point.expenses;return{points,hasRevenue:false,hasExpenses:points.some(point=>point.expenses!==0),hasQuotes:points.some(point=>point.quoted!==0)}}
function buildFinanceChartSvg(series,metric='Revenue',period='All'){const key={'Revenue':'revenue','Expenses':'expenses','Profit':'profit','Quoted Pipeline':'quoted'}[metric]||'revenue',points=series.points||[],hasData=key==='revenue'?series.hasRevenue:key==='expenses'?series.hasExpenses:key==='profit'?series.hasProfit:series.hasQuotes;const emptyNote=!hasData?(key==='revenue'?'No actual payments recorded yet. Quotes are not revenue.':key==='profit'?'Profit requires recorded revenue; expense-only figures are not profit.':key==='expenses'?'No expenses in this period.':'No quotes in this period.'):'';const values=points.map(point=>Number(point[key]||0)),minimum=Math.min(0,...values),maximum=Math.max(0,...values),span=maximum-minimum||1,width=760,height=220,margin={top:12,right:12,bottom:28,left:12},baseY=height-margin.bottom-(0-minimum)/span*(height-margin.top-margin.bottom),coordinates=values.map((value,index)=>[margin.left+index/Math.max(1,values.length-1)*(width-margin.left-margin.right),height-margin.bottom-(value-minimum)/span*(height-margin.top-margin.bottom)]),line=coordinates.map((point,index)=>`${index?'L':'M'} ${point[0]} ${point[1]}`).join(' '),area=`${line} L ${coordinates[coordinates.length-1][0]} ${baseY} L ${coordinates[0][0]} ${baseY} Z`,dots=coordinates.filter((point,index)=>index===coordinates.length-1||values[index]!==0).map(point=>`<circle cx="${point[0]}" cy="${point[1]}" r="3" fill="#22c0b3"/>`).join(''),total=values.reduce((sum,value)=>sum+value,0),firstDate=points[0]?.date.toLocaleDateString('en-IE',{month:'short',year:'2-digit'})||'',lastDate=points[points.length-1]?.date.toLocaleDateString('en-IE',{month:'short',year:'2-digit'})||'';return `${emptyNote?`<p class="muted sub" role="status">${emptyNote}</p>`:""}<div class="chart-shell"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(metric)} by date for ${esc(period)}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#22c0b3" stop-opacity=".4"/><stop offset="100%" stop-color="#22c0b3" stop-opacity=".03"/></linearGradient></defs><path d="${area}" fill="url(#chartFill)"/><path d="${line}" fill="none" stroke="#22c0b3" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${dots}<text x="${margin.left}" y="${height-5}" fill="#c6d7df" font-size="11">${esc(firstDate)}</text><text x="${width-margin.right}" y="${height-5}" fill="#c6d7df" font-size="11" text-anchor="end">${esc(lastDate)}</text></svg></div><div class="chart-summary"><span class="muted sub">${metric==='Quoted Pipeline'?'Quote value in period':'Net recorded amount in period'}</span><strong>${euro(total)}</strong></div><p class="muted sub">Only expenses and quote amounts are stored today; accepted quotes are not revenue. Revenue entries are not yet supported.</p>`}
const tfNavIcons={"dashboard":"<svg viewBox=\"0 0 24 24\" width=\"23\" height=\"23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 10 9-7 9 7v10H3z\"/><path d=\"M9 20v-7h6v7\"/></svg>","map":"<svg viewBox=\"0 0 24 24\" width=\"23\" height=\"23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z\"/><path d=\"M9 3v15M15 6v15\"/></svg>","opportunities":"<svg viewBox=\"0 0 24 24\" width=\"23\" height=\"23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"1.5\"/><path d=\"m12 12 8-8\"/></svg>","expenses":"<svg viewBox=\"0 0 24 24\" width=\"23\" height=\"23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 20V12M9 20V6M14 20v-9M19 20V3\"/></svg>","settings":"<svg viewBox=\"0 0 24 24\" width=\"23\" height=\"23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"5\" cy=\"6\" r=\"1\"/><circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"5\" cy=\"18\" r=\"1\"/><path d=\"M10 6h11M10 12h11M10 18h11\"/></svg>"};
async function render(){prefs={...prefs,...(await get('settings','business')||{})};document.documentElement.style.setProperty('--brand-accent',prefs.accent);const data=Object.fromEntries(await Promise.all(STORES.map(async store=>[store,await all(store)]))),nav=Object.keys(names).map(key=>`<button class="nav ${tab===key?'active':''}" data-tab="${key}">${icons[key]} &nbsp; ${names[key]}</button>`).join(''),mobile=[['dashboard','Home',tfNavIcons.dashboard],['map','Map',tfNavIcons.map],['opportunities','Opportunities',tfNavIcons.opportunities],['expenses','Finance',tfNavIcons.expenses],['settings','More',tfNavIcons.settings]].map(([key,label,icon])=>`<button data-tab="${key}" class="${tab===key?'active':''}"><span class="navicon" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${esc(prefs.company)} <small style="font-size:10px;color:#a4bdc8">LITE</small></div>${nav}</aside><div class="main"><header class="top"><strong>${tab==='dashboard'?'Home':tab==='settings'?'More':tab==='expenses'?'Finance':names[tab]}</strong><span class="muted sub">Offline-first · Data stays on this device</span></header><main class="content">${toast?`<div class="notice" role="status">${esc(toast)}</div>`:''}${view(data)}</main><nav class="mobilebar">${mobile}</nav></div></div>${modal?formModal(data):''}`;if(tab==='map')setTimeout(()=>initializeMap(data),0)}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-map-action]');if(button){event.preventDefault();event.stopImmediatePropagation();const panel=button.closest('.tf-location-sheet');await handleMapAction(button.dataset.mapAction,{lat:button.dataset.lat,lng:button.dataset.lng,address:button.dataset.address,customerId:panel?.querySelector('[data-link-customer]')?.value,jobId:panel?.querySelector('[data-link-job]')?.value});return}const period=event.target.closest('[data-finance-period]');if(period){event.preventDefault();event.stopImmediatePropagation();financeState.period=period.dataset.financePeriod;render();return}const metric=event.target.closest('[data-finance-metric]');if(metric){event.preventDefault();event.stopImmediatePropagation();financeState.metric=metric.dataset.financeMetric;render()}},true)
